    const mine = live?.members.find((m) => m.user === ME)?.state
    const callbar = $(".dm-callbar")
    // My own call still ringing on another device can't be moved: nothing to move yet.
    callbar.hidden = !live || !callable || callUI.inCall(live.id) || mine === "ringing" || (mine === "joined" && !live.answeredAt)
