      // Already in it on another device (the phone app): joining moves the call here.
      callbar.innerHTML =
        mine === "joined"
          ? `${svg(live.video ? "video" : "phone")}<span>${t("On this call on another device", "أنت في هذه المكالمة على جهاز آخر")}</span><b>${t("Move here", "انقلها هنا")}</b>`
          : `${svg(live.video ? "video" : "phone")}<span>${live.video ? t("Video call in progress", "مكالمة فيديو جارية") : t("Voice call in progress", "مكالمة صوتية جارية")}</span><b>${t("Join", "انضمام")}</b>`
